#include <iostream>
#include <cmath>
using namespace std;

int main() {
    double x1, y1, x2, y2, x3, y3;
    // Uchburchakning uchlari koordinatalarini kiritish
    cout << "Birinchi nuqtaning koordinatalarini kiritish (x1, y1): ";
    cin >> x1 >> y1;
    cout << "Ikkinchi nuqtaning koordinatalarini kiritish (x2, y2): ";
    cin >> x2 >> y2;
    cout << "Uchinchi nuqtaning koordinatalarini kiritish (x3, y3): ";
    cin >> x3 >> y3;

    // Uchburchakning uch tomonining uzunliklarini hisoblash
    double a = sqrt(pow(x2 - x1, 2) + pow(y2 - y1, 2));
    double b = sqrt(pow(x3 - x2, 2) + pow(y3 - y2, 2));
    double c = sqrt(pow(x1 - x3, 2) + pow(y1 - y3, 2));

    // Perimetrni hisoblash
    double perimeter = a + b + c;

    // Yuzani hisoblash uchun Heron formulasi
    double s = perimeter / 2;
    double area = sqrt(s * (s - a) * (s - b) * (s - c));

    // Natijalarni chiqarish
    cout << "Uchburchakning perimetri: " << perimeter << endl;
    cout << "Uchburchakning yuzi: " << area << endl;
    return 0;
}

#include <iostream>
