int main() {
    double X;
    // X qiymatini kiritish
    cout << "X sonini kiriting: ";
    cin >> X;

    // Yordamchi o'zgaruvchilar
    double X2, X4, X5;
    // X² ni hisoblash (1-ko'paytirish)
    X2 = X * X;
    // X⁴ ni hisoblash (2-ko'paytirish: X² ning kvadrati)
    X4 = X2 * X2;
    // X⁵ ni hisoblash (3-ko'paytirish: X * X⁴)
    X5 = X * X4;

    // Natijalarni chiqarish
    cout << "X^2: " << X2 << endl;
    cout << "X^4: " << X4 << endl;
    cout << "X^5: " << X5 << endl;
    return 0;
}

