#include <iostream>
using namespace std;

int main() {
    int x;
    cout << "Uch xonali sonni kiriting: ";
    cin >> x;

    // Raqamlarni ajratib olish
    int A = x / 100;
    int B = (x / 10) % 10;
    int C = x % 10;

    // a) Barcha raqamlar bir xilmi?
    if (A == B && B == C) {
        cout << "Barcha raqamlar bir xil." << endl;
    } else {
        cout << "Barcha raqamlar bir xil emas." << endl;
    }

    // b) Hech bo'lmaganda ikkita raqam bir xilmi?
    if (A == B || B == C || A == C) {
        cout << "Hech bo'lmaganda ikkita raqam bir xil." << endl;
    } else {
        cout << "Barcha raqamlar har xil." << endl;
    }
    return 0;
}

