using namespace std;

int main() {
    int x1, y1, x2, y2;
    int x3, y3, x4, y4;

    // Birinchi to'rtburchak koordinatalari
    cout << "Birinchi to'rtburchak (x1, y1, x2, y2): ";
    cin >> x1 >> y1 >> x2 >> y2;
    // Ikkinchi to'rtburchak koordinatalari
    cout << "Ikkinchi to'rtburchak (x3, y3, x4, y4): ";
    cin >> x3 >> y3 >> x4 >> y4;

    // Minimal X va Y topish
    int Xmin = x1;
    if (x3 < Xmin) Xmin = x3;
    int Ymin = y1;
    if (y3 < Ymin) Ymin = y3;

    // Maksimal X va Y topish
    int Xmax = x2;
    if (x4 > Xmax) Xmax = x4;
    int Ymax = y2;
    if (y4 > Ymax) Ymax = y4;

    // Natijani chiqarish
    cout << "Minimal to'rtburchak koordinatalari:\n";
    cout << "Pastki chap burchak: (" << Xmin << ", " << Ymin << ")\n";
    cout << "Yuqori o'ng burchak: (" << Xmax << ", " << Ymax << ")\n";
    return 0;
}

